import '../qa/resolve-vendor.mjs';import assert from 'node:assert/strict';import fs from 'node:fs';const {createAncientTree}=await import('../src/trees.js'),THREE=await import('../vendor/three.module.js');const reports=[];
for(const dead of [true,false]){const tree=createAncientTree({dead,volume:true,coreResolution:dead?96:112,coreBlend:.22,coreHollow:.5}),g=tree.core.geometry,p=g.attributes.position,n=g.attributes.normal;assert.ok(tree.evidence().connected);assert.ok(tree.evidence().growthVContinuous);assert.ok(p.array.every(Number.isFinite));assert.ok(n.array.every(Number.isFinite));assert.ok(g.attributes.growthV.array.every(Number.isFinite));assert.ok(g.attributes.axisId.array.every(v=>Number.isInteger(v)&&v>=0&&v<tree.axes.length));assert.ok(tree.core.stats.topology.closed);assert.ok(tree.core.stats.topology.signedVolume>0);for(const w of tree.core.windows)assert.equal(tree.core.contains(w.origin.clone().addScaledVector(w.rad,w.radii[2]*.15)),false,'surface window actually joins inner void to outside');const trunk=tree.byId.get('trunk'),center=trunk.path.getPointAt(.5);assert.equal(tree.core.contains(center),false,'real internal cavity at trunk centre');const tangent=trunk.path.getTangentAt(.5),back=new THREE.Vector3(0,0,-1).addScaledVector(tangent,-new THREE.Vector3(0,0,-1).dot(tangent)).normalize(),wall=center.clone().addScaledVector(back,trunk.radiusAt(.5)*.86);assert.equal(tree.core.contains(wall),true,'back shell retains solid wall');let signedVolume=0,innerNormals=0;for(let i=0;i<g.index.count;i+=3){const a=new THREE.Vector3().fromBufferAttribute(p,g.index.getX(i)),b=new THREE.Vector3().fromBufferAttribute(p,g.index.getX(i+1)),c=new THREE.Vector3().fromBufferAttribute(p,g.index.getX(i+2));signedVolume+=a.dot(b.cross(c))/6;}assert.ok(signedVolume>0);for(let i=0;i<p.count;i++){const point=new THREE.Vector3().fromBufferAttribute(p,i),axis=g.attributes.axisId.getX(i);if(axis===0){const u=g.attributes.uv.getY(i)/trunk.path.getLength(),radial=point.sub(trunk.path.getPointAt(u));if(radial.dot(new THREE.Vector3().fromBufferAttribute(n,i))<0)innerNormals++;}}assert.ok(innerNormals>100,'actual inward-facing cavity surface normals');const edges=new Map();for(let i=0;i<g.index.count;i+=3)for(let j=0;j<3;j++){const a=g.index.getX(i+j),b=g.index.getX(i+(j+1)%3),k=Math.min(a,b)+','+Math.max(a,b);edges.set(k,(edges.get(k)||0)+1);}assert.ok([...edges.values()].every(n=>n===2),'closed core shell: every indexed edge paired exactly twice');reports.push({dead,...tree.core.stats,signedVolume,innerSurfaceVertices:innerNormals,axisGraphRetained:true,centreIsVoid:true,backWallIsSolid:true,closedIndexedSurface:true});}
fs.writeFileSync('qa/volume-core-report.json',JSON.stringify({pass:true,reports},null,2)+'\n');console.log(reports);
